draw:
function draw(ctx, state, t) {
  var top = 36;
  var bot = 286;
  var thr = 400;
  var nkv = state.nkv;
  var nq = state.nq;
  function fmt(v) { return Math.round(v * 100) / 100; }
  var scale = 250 / 1024;
  var Lmax = 128;
  var cache = nkv * Lmax;
  var yend = cache * scale;
  var ythr = bot - thr * scale;
  var i = 0;
  var g = 0;
  var bw = 0;
  var bx = 0;
  var by = 252;
  var bh = 22;
  ctx.clearRect(0, 0, state.w, state.h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, state.w, state.h);
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(48, bot);
  if (yend > bot - top) {
    ctx.lineTo(560, top);
    ctx.stroke();
    ctx.fillStyle = "#1f4b99";
    ctx.font = "12px sans-serif";
    ctx.fillText("clipped", 500, top + 16);
  } else {
    ctx.lineTo(560, bot - yend);
    ctx.stroke();
  }
  ctx.strokeStyle = "#c4512c";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(48, ythr);
  ctx.lineTo(560, ythr);
  ctx.stroke();
  ctx.fillStyle = "#c4512c";
  ctx.font = "12px sans-serif";
  ctx.fillText("threshold " + fmt(thr), 48, ythr - 8);
  bw = 512 / nq;
  for (i = 0; i < nq; i++) {
    g = Math.floor(i * nkv / nq);
    bx = 48 + i * bw + g * 4;
    if (g % 2 === 0) { ctx.fillStyle = "#1f4b99"; } else { ctx.fillStyle = "#2e7d4f"; }
    ctx.fillRect(bx, by, bw - 2, bh);
  }
  ctx.fillStyle = "#1f4b99";
  ctx.font = "12px sans-serif";
  ctx.fillText("cache = " + fmt(cache), 48, 318);
  ctx.fillText("group " + fmt(nq) + " over " + fmt(nkv), 320, 318);
  ctx.fillText("toy nkv x L", 48, 344);
}
